import {panorama} from './panorama.js';
import {registerAndSignIn} from './auth.js';
import {TempleScene} from './scene.js';
import {getClient,configured,getConfig,errorText} from './cloud.js';
const $=s=>document.querySelector(s);const scene=new TempleScene($('#landscape'),{preview:false});panorama(scene);scene.player.name='';scene.player.x=410;scene.player.y=900;
let mode='login',client,busy=false,currentSession=null;function message(text){$('#authMessage').textContent=text}function setMode(next){mode=next;$('#nameWrap').hidden=mode!=='signup';$('#displayName').required=mode==='signup';$('#password').required=mode!=='forgot';$('.password-field').hidden=mode==='forgot';$('.password-label').hidden=mode==='forgot';$('.auth-tabs').hidden=mode==='reset';$('#email').closest('form').querySelector('label[for=email]').hidden=mode==='reset';$('#email').hidden=mode==='reset';$('#email').required=mode!=='reset';$('#password').autocomplete=mode==='login'?'current-password':'new-password';$('#authTitle').textContent={login:'Chào bạn trở về.',signup:'Gieo duyên từ hôm nay.',forgot:'Tìm lại lối về chùa.',reset:'Đặt lại mật khẩu.'}[mode];$('#authIntro').textContent=mode==='forgot'?'Nhận đường dẫn đặt lại mật khẩu qua email.':mode==='signup'?'Tạo tài khoản để bắt đầu hành trình an nhiên.':'Đăng nhập để giữ lại hành trình an nhiên.';$('#submitAuth').textContent={login:'Vào chùa ↗',signup:'Tạo tài khoản ↗',forgot:'Gửi email khôi phục ↗',reset:'Lưu mật khẩu mới ↗'}[mode];document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===mode));message('')}
async function init(){if(configured())$('.setup').hidden=true;if(!configured()){$('#connection').textContent='○ Chưa nối Supabase · Có thể vào chơi khách';return}try{client=await getClient();const {data,error}=await client.auth.getSession();if(error)throw error;$('#connection').textContent='● Hành trình được lưu và đồng bộ';$('#connection').classList.add('connected');client.auth.onAuthStateChange(event=>{if(event==='PASSWORD_RECOVERY')setMode('reset')});if(location.hash.includes('type=recovery'))setMode('reset');else if(data.session){currentSession=data.session;$('#authIntro').textContent='Bạn đã đăng nhập. Chạm “Vào chùa” để tiếp tục.';$('#email').value=data.session.user.email||'';$('#password').required=false}}catch(e){$('#connection').textContent='○ Kết nối Supabase chưa thành công';message(errorText(e))}}
$('#authForm').onsubmit=async e=>{e.preventDefault();if(busy)return;if(!configured()){message('Chưa có project Supabase. Chủ chùa cần nối project để mở đăng nhập. Bạn có thể dạo chùa với tư cách khách.');return}busy=true;$('#submitAuth').disabled=true;message('Đang kết nối…');try{client=await getClient();const email=$('#email').value.trim(),password=$('#password').value;if(mode==='login'&&currentSession&&email===currentSession.user.email&&!password){sessionStorage.setItem('annhien-mode','cloud');location.href='game.html';return}if(mode==='login'){const {error}=await client.auth.signInWithPassword({email,password});if(error)throw error;sessionStorage.setItem('annhien-mode','cloud');location.href='game.html'}else if(mode==='signup'){await registerAndSignIn(client,{email,password,displayName:$('#displayName').value.trim()});sessionStorage.setItem('annhien-mode','cloud');location.href='game.html'}else if(mode==='forgot'){const {error}=await client.auth.resetPasswordForEmail(email,{redirectTo:location.origin+'/index.html'});if(error)throw error;message('Nếu email đã đăng ký, bạn sẽ nhận được đường dẫn khôi phục.')}else{const {error}=await client.auth.updateUser({password});if(error)throw error;setMode('login');message('Đã đổi mật khẩu. Bạn có thể vào chùa.')}}catch(e){message(errorText(e))}finally{busy=false;$('#submitAuth').disabled=false}};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$('#forgot').onclick=()=>setMode('forgot');$('#showPassword').onclick=()=>{const p=$('#password');p.type=p.type==='password'?'text':'password';$('#showPassword').setAttribute('aria-label',p.type==='password'?'Hiện mật khẩu':'Ẩn mật khẩu')};$('#guest').onclick=()=>{sessionStorage.setItem('annhien-mode','guest');location.href='game.html'};const config=getConfig();$('#projectUrl').value=config.supabaseUrl||'';$('#publicKey').value=config.supabaseKey||'';$('#configForm').onsubmit=e=>{e.preventDefault();const url=$('#projectUrl').value.trim(),key=$('#publicKey').value.trim();let parsed;try{parsed=new URL(url)}catch{return message('Project URL chưa hợp lệ.')}if(parsed.protocol!=='https:')return message('Project URL phải dùng HTTPS.');if(key.startsWith('sb_secret_'))return message('Không dùng secret key trong trình duyệt.');try{const payload=JSON.parse(atob(key.split('.')[1]));if(payload.role==='service_role')return message('Không dùng service_role key trong trình duyệt.')}catch{}localStorage.setItem('annhien-cloud',JSON.stringify({supabaseUrl:url.replace(/\/$/,''),supabaseKey:key}));location.reload()};init();
